{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "The closest high-transfer analogue, SCH 23390, showed rapid transfer of radioactivity into human brain by PET, with 1.2% of injected dose in brain at 4.5 min, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A closely related iodo-substituted benzazepine showed 1.59% dose/organ brain uptake at 2 min after IV injection in rats, indicating good blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Another close benzazepine analogue, [125I]FISCH, exhibited good brain uptake in rats (2.27% dose/whole brain at 2 min), supporting CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A des-chloro analogue showed a brain-to-blood ratio of about 1.2 at 10 min in rats, indicating active brain uptake rather than exclusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The related benzazepine/apomorphine scaffold achieved a brain AUC/plasma AUC of 228% in mice, confirming that this structural family can achieve high CNS exposure after systemic dosing.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a SCH 23390-type benzazepine with the same CNS-active scaffold. Multiple direct human PET/SPECT and rodent biodistribution studies on close analogues demonstrate robust brain uptake and meaningful CNS access. The added nitro and dihydrobenzofuran groups do not introduce a clear barrier based on the consistent positive phenotype of this chemotype.",
  "evidence_gaps": [
    "No direct brain/plasma PK measurement for the exact nitro/dihydrobenzofuran query molecule.",
    "Efflux-transporter status of the query was not explicitly measured, though close analogues show good brain uptake without transporter inhibition."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

